#version 120

varying vec4 color;
varying vec2 texcoord;
varying vec2 lmcoord;

void main() {
    gl_Position = ftransform();
    color = gl_Color;
    texcoord = gl_MultiTexCoord0.xy;
    lmcoord = gl_MultiTexCoord1.xy;
}

#version 120

uniform sampler2D gtexture;
uniform sampler2D lightmap;

varying vec4 color;
varying vec2 texcoord;
varying vec2 lmcoord;

void main() {
    vec3 col = texture2D(gtexture, texcoord).rgb * color.rgb;
    vec3 light = texture2D(lightmap, lmcoord).rgb;

    // Simple voxel-like lighting (ambient + lightmap)
    gl_FragColor = vec4(col * light, 1.0);
}

#version 120

varying vec4 color;
varying vec2 texcoord;
varying vec2 lmcoord;

uniform float frameTimeCounter;
uniform vec3 cameraPosition;

attribute vec4 mc_Entity;

void main() {
    vec4 position = gl_Vertex;

    // Waving foliage (leaves = 18, grass = 31)
    if (mc_Entity.x == 18.0 || mc_Entity.x == 31.0) {
        float speed = 1.5;
        float magnitude = 0.1;
        position.x += sin(frameTimeCounter * speed + position.x + position.y + position.z) * magnitude;
    }

    gl_Position = gl_ModelViewProjectionMatrix * position;
    color = gl_Color;
    texcoord = gl_MultiTexCoord0.xy;
    lmcoord = gl_MultiTexCoord1.xy;
}

#version 120

uniform sampler2D gtexture;
uniform sampler2D lightmap;

varying vec4 color;
varying vec2 texcoord;
varying vec2 lmcoord;

void main() {
    vec3 col = texture2D(gtexture, texcoord).rgb * color.rgb;
    vec3 light = texture2D(lightmap, lmcoord).rgb;
    gl_FragColor = vec4(col * light, texture2D(gtexture, texcoord).a);
}

#version 120

varying vec4 color;
varying vec2 texcoord;
varying vec2 lmcoord;
varying vec3 normal;

uniform float frameTimeCounter;

void main() {
    vec4 position = gl_Vertex;

    // Waving water
    float speed = 2.0;
    float magnitude = 0.05;
    position.y += sin(frameTimeCounter * speed + position.x + position.z) * magnitude;

    gl_Position = gl_ModelViewProjectionMatrix * position;
    color = gl_Color;
    texcoord = gl_MultiTexCoord0.xy;
    lmcoord = gl_MultiTexCoord1.xy;
    normal = gl_NormalMatrix * gl_Normal;
}

#version 120

uniform sampler2D gtexture;
uniform sampler2D lightmap;
uniform float frameTimeCounter;

varying vec4 color;
varying vec2 texcoord;
varying vec2 lmcoord;
varying vec3 normal;

void main() {
    // Fake reflection/distortion
    vec2 distortedTexcoord = texcoord + vec2(sin(frameTimeCounter + texcoord.y * 10.0), cos(frameTimeCounter + texcoord.x * 10.0)) * 0.01;

    vec4 col = texture2D(gtexture, distortedTexcoord) * color;
    vec3 light = texture2D(lightmap, lmcoord).rgb;

    // Simple blue tint for water
    col.rgb *= vec3(0.8, 0.9, 1.0);

    gl_FragColor = vec4(col.rgb * light, col.a * 0.8); // Semi-transparent
}

